package gov.takx.api.explorer;

/**
 * Interface for an explorable rule factory.
 *
 * @since 1.48
 */
public interface IExplorableRuleFactory<T extends IExplorableRule>
{
    /**
     * Create a new explorable rule instance.
     *
     * @return new explorable rule instance.
     */
    T createRule();

    /**
     * Get the explorable rule factory's display name.
     *
     * @return explorable rule factory's display name.
     */
    String getDisplayName();

    /**
     * Get the explorable rule type generated by this factory.
     *
     * @return the explorable rule type generated by this factory.
     */
    String getType();
}
